// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the from address, uint value and a single recipient in the _tos array by fuzzing address and amount
    function testFuzz_property(address from, uint256 v, address dummy) public {
        // Keep _tos non-empty as required by the contract
        vm.assume(dummy != address(0));

        // Deploy a recorder that exposes the exact expected function signature used by the reference implementation:
        // function transferFrom(address from, address to, uint256 v) external returns (bool)
        Recorder r = new Recorder();

        // Build a single-entry _tos array
        address[] memory tos = new address[](1);
        tos[0] = address(r);

        bool ok;
        // call c.transfer and capture whether it succeeds (reference should succeed for all inputs here)
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract ALWAYS performs a well-formed call with selector transferFrom(...)
        // to the callee; our Recorder implements that exact function and always returns true, so
        // the reference implementation must never revert and ok must be true for all admissible inputs.
        // The mutant that changes the selector to transfer(...) will typically call a non-existent
        // function on Recorder, causing the call to fail and ok to be false for some inputs. Thus
        // require that ok is true here — this holds for the reference for all inputs and is violated
        // by the mutant for some inputs.
        assertTrue(ok);

        // Additionally, verify the Recorder observed exactly one call with the decoded arguments
        // to ensure the external behavior happened as expected (observability check through helper).
        (address observedFrom, address observedTo, uint256 observedV, uint256 calls) = r.getLast();
        assertTrue(calls == 1);
        assertTrue(observedFrom == from);
        assertTrue(observedTo == tos[0]);
        assertTrue(observedV == v);
    }
}

// Recorder implements the exact signature expected by the reference implementation so it will
// be invoked successfully by the reference contract. It records the last call's arguments and
// a call counter.
contract Recorder {
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;
    uint256 public calls;

    // Exact signature: transferFrom(address,address,uint256)
    function transferFrom(address _from, address _to, uint256 _v) external returns (bool) {
        lastFrom = _from;
        lastTo = _to;
        lastV = _v;
        calls += 1;
        return true;
    }

    // getter to expose the recorded values to the test
    function getLast() external view returns (address, address, uint256, uint256) {
        return (lastFrom, lastTo, lastV, calls);
    }
}
